from hourglass.parsing import format_span
from hourglass.models import Span

# ---
def round_spans(spans: list[Span], step: int) -> list[str]:
    """Snap each span to the nearest step, then label it."""
    if step <= 0 or 60 % step:
        raise ValueError(f"bad step: {step}")
    labels = []
    for span in spans:
        start = _snap(span.start, step)
        end = _snap(span.end, step)
        rounded = Span(start, end)
        hours, minutes = divmod(rounded.minutes, 60)
        labels.append(
            f"{format_span(rounded)} ({hours}h {minutes}m)"
        )
    return labels

def _snap(minute: int, step: int) -> int:
    return (2 * minute + step) // (2 * step) * step

