# owner: platform
import unittest

from hourglass.rounding import round_spans
from hourglass.models import Span


class RoundSpansTests(unittest.TestCase):
    def test_snaps_to_nearest_step(self):
        self.assertEqual(
            round_spans([Span(544, 1034)], 15),
            ["09:00-17:15 (8h 15m)"]
        )

    def test_exact_values_unchanged(self):
        self.assertEqual(
            round_spans([Span(540, 600)], 30),
            ["09:00-10:00 (1h 0m)"]
        )

    def test_bad_steps_raise(self):
        for step in (0, -15, 7, 45):
            with self.assertRaises(ValueError):
                round_spans([Span(540, 600)], step)
